"""Provided command-line runner. Do not edit this file."""
import argparse
from inference import filter_sequence, predict, predict_steps
from models import get_model, SEQUENCES


def main():
    parser = argparse.ArgumentParser(description="Run HMM filtering and prediction")
    parser.add_argument("--model", choices=["umbrella", "three_state", "reliable", "noisy", "persistent", "weak"], default="umbrella")
    parser.add_argument("--sequence", choices=SEQUENCES, default="classroom")
    parser.add_argument("--observations", help="Override sequence, e.g. U,N,U. Use an empty string for no evidence.")
    parser.add_argument("--steps", type=int, nargs="*", default=[1, 2, 5, 10])
    args = parser.parse_args()
    if any(k < 0 for k in args.steps):
        parser.error("Prediction steps must be nonnegative")
    model = get_model(args.model)
    obs = SEQUENCES[args.sequence]
    if args.observations is not None:
        tokens = [v.strip().upper() for v in args.observations.split(",")] if args.observations.strip() else []
        if any(v not in model.symbols for v in tokens):
            parser.error("Observations must be comma-separated U or N")
        obs = [model.symbols.index(v) for v in tokens]
    beliefs = filter_sequence(model.prior, obs, model.transition, model.sensor)
    print("Model:", args.model, "| state order:", ", ".join(model.states))
    print("b_0:", " ".join(f"{p:.9f}" for p in model.prior))
    previous = model.prior
    for t, (e, belief) in enumerate(zip(obs, beliefs), start=1):
        predicted = predict(previous, model.transition)
        print(f"Day {t} | {model.symbols[e]} | predicted:", " ".join(f"{p:.9f}" for p in predicted),
              "| filtered:", " ".join(f"{p:.9f}" for p in belief))
        previous = belief
    final = beliefs[-1] if beliefs else model.prior
    for k in args.steps:
        print(f"Future +{k}:", " ".join(f"{p:.9f}" for p in predict_steps(final, model.transition, k)))


if __name__ == "__main__":
    main()
